// Live verification for ENG-2409 collapsible/sticky settings headings.
import fs from "node:fs";
import path from "node:path";

const MODE = process.env.VERIFY_MODE || "after";
const SHOT_DIR =
  "/private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/23e2695a-e848-4726-8a24-c535b2593640/scratchpad/verify/shots";
fs.mkdirSync(SHOT_DIR, { recursive: true });

const dialogSel = ".bp3-dialog:has(.dg-settings-tabs)";

export default {
  async run({ page }) {
    const results = {};
    const consoleErrors = [];
    page.on("console", (m) => {
      if (m.type() === "error") consoleErrors.push(m.text().slice(0, 300));
    });
    page.on("pageerror", (e) => consoleErrors.push("pageerror: " + e.message));

    const dialog = page.locator(dialogSel).last();
    await dialog.waitFor({ timeout: 20000 });
    const shot = async (name) => {
      const p = path.join(SHOT_DIR, `${MODE}-${name}.png`);
      await dialog.screenshot({ path: p });
      return p;
    };
    const clickTab = async (label) => {
      await dialog
        .locator(".bp3-tab")
        .filter({ hasText: new RegExp(`^${label}$`) })
        .first()
        .click();
      await page.waitForTimeout(600);
    };
    const openNode = async (name) => {
      await clickTab("Nodes");
      const back = dialog.locator("button[aria-label^='Back to']");
      for (let i = 0; i < 3 && (await back.count()); i++) {
        await back.first().click();
        await page.waitForTimeout(400);
      }
      await dialog.locator("td").filter({ hasText: new RegExp(`^${name}$`) }).first().click();
      await page.waitForTimeout(800);
    };
    // Measures headings with text in the active panel against their scroll box.
    const measure = (headingText) =>
      page.evaluate(
        ({ dialogSel, headingText }) => {
          const d = [...document.querySelectorAll(dialogSel)].pop();
          const panel = d.querySelector(".bp3-tab-panel[aria-hidden='false']") || d;
          const all = [...panel.querySelectorAll(".bp3-heading")];
          const h = all.find((e) => e.textContent.trim() === headingText);
          if (!h) return { found: false, headings: all.map((e) => e.textContent.trim()) };
          let box = h.parentElement;
          while (box && !/(auto|scroll)/.test(getComputedStyle(box).overflowY)) box = box.parentElement;
          const cs = getComputedStyle(h);
          return {
            found: true,
            position: cs.position,
            bg: cs.backgroundColor,
            color: cs.color,
            zIndex: cs.zIndex,
            headingTop: Math.round(h.getBoundingClientRect().top * 10) / 10,
            boxTop: box ? Math.round(box.getBoundingClientRect().top * 10) / 10 : null,
            scrollTop: box?.scrollTop,
            scrollHeight: box?.scrollHeight,
            clientHeight: box?.clientHeight,
            ariaExpanded: h.getAttribute("aria-expanded"),
            role: h.getAttribute("role"),
          };
        },
        { dialogSel, headingText },
      );
    // Scrolls the heading's scroll box so its top lands `offset` px into the heading's group.
    const scrollInto = (headingText, offset) =>
      page.evaluate(
        ({ dialogSel, headingText, offset }) => {
          const d = [...document.querySelectorAll(dialogSel)].pop();
          const h = [...d.querySelectorAll(".bp3-heading")].find(
            (e) => e.textContent.trim() === headingText,
          );
          const group = h.parentElement;
          let box = h.parentElement;
          while (box && !/(auto|scroll)/.test(getComputedStyle(box).overflowY)) box = box.parentElement;
          const delta = group.getBoundingClientRect().top - box.getBoundingClientRect().top;
          const want = Math.min(offset, group.getBoundingClientRect().height - 40);
          box.scrollTop += delta + want;
          return { groupHeight: group.getBoundingClientRect().height, scrollTop: box.scrollTop };
        },
        { dialogSel, headingText, offset },
      );
    const expandedStates = () =>
      page.evaluate((dialogSel) => {
        const d = [...document.querySelectorAll(dialogSel)].pop();
        return [...d.querySelectorAll("[role=button][aria-expanded]")].map((e) => [
          e.textContent.trim(),
          e.getAttribute("aria-expanded"),
        ]);
      }, dialogSel);
    const toggleAllBtn = () =>
      dialog.locator("button").filter({ hasText: /^(Collapse all|Expand all)$/ });
    const step = async (key, fn) => {
      try {
        results[key] = await fn();
      } catch (e) {
        results[key] = { error: String(e?.message || e).slice(0, 400) };
        await shot(`${key}-error`).catch(() => {});
      }
    };
    const near = (a, b) => a != null && b != null && Math.abs(a - b) <= 2;

    if (MODE === "after") {
      await step("A", async () => {
        await openNode("Claim");
        const states = await expandedStates();
        const btn = (await toggleAllBtn().innerText()).trim();
        return {
          pass: btn === "Collapse all" && states.length > 0 && states.every(([, v]) => v === "true"),
          btn,
          states,
          shot: await shot("A-node-default"),
        };
      });
      await step("B", async () => {
        await toggleAllBtn().click();
        await page.waitForTimeout(300);
        const states = await expandedStates();
        const btn = (await toggleAllBtn().innerText()).trim();
        return {
          pass: btn === "Expand all" && states.every(([, v]) => v === "false"),
          btn,
          states,
          shot: await shot("B-collapse-all"),
        };
      });
      await step("C", async () => {
        await toggleAllBtn().click();
        await page.waitForTimeout(300);
        const scrolled = await scrollInto("Canvas", 150);
        await page.waitForTimeout(300);
        const m = await measure("Canvas");
        return {
          pass: m.position === "sticky" && near(m.headingTop, m.boxTop),
          scrolled,
          m,
          shot: await shot("C-canvas-stuck"),
        };
      });
      await step("D", async () => {
        await dialog.locator("[role=button][aria-expanded]").filter({ hasText: /^Canvas$/ }).click();
        await page.waitForTimeout(400);
        const m = await measure("Canvas");
        return {
          pass: m.ariaExpanded === "false" && near(m.headingTop, m.boxTop),
          m,
          shot: await shot("D-canvas-collapsed-from-stuck"),
        };
      });
      await step("E", async () => {
        // Reset: expand all, then collapse only Legacy.
        if ((await toggleAllBtn().innerText()).trim() === "Collapse all") {
          await toggleAllBtn().click();
          await page.waitForTimeout(200);
        }
        await toggleAllBtn().click(); // now all expanded
        await page.waitForTimeout(200);
        await dialog.locator("[role=button][aria-expanded]").filter({ hasText: /^Legacy$/ }).click();
        await page.waitForTimeout(200);
        const beforeSwitch = await expandedStates();
        await openNode("Evidence");
        const afterSwitch = await expandedStates();
        const legacy = afterSwitch.find(([t]) => t === "Legacy");
        const title = await dialog.locator(".text-2xl").first().innerText();
        return {
          pass: legacy?.[1] === "false" && afterSwitch.filter(([, v]) => v === "false").length === 1,
          title: title.trim(),
          beforeSwitch,
          afterSwitch,
          shot: await shot("E-evidence-legacy-still-collapsed"),
        };
      });
      await step("F", async () => {
        await openNode("Claim");
        if ((await toggleAllBtn().innerText()).trim() === "Collapse all") {
          await toggleAllBtn().click();
          await page.waitForTimeout(200);
        }
        const collapsedBefore = await expandedStates();
        const input = dialog.locator("input[placeholder='Search settings']");
        await input.click();
        await input.fill("Overlay");
        await page.waitForTimeout(600);
        const items = page.locator(".bp3-popover .bp3-menu-item");
        const texts = await items.allInnerTexts();
        const idx = texts.findIndex((t) => /Claim/.test(t) && /Overlay/.test(t));
        if (idx < 0) throw new Error("No Claim Overlay result: " + JSON.stringify(texts));
        await items.nth(idx).dispatchEvent("mousedown");
        await page.waitForTimeout(450);
        const flashShot = await shot("F-search-overlay-flash");
        const states = await expandedStates();
        const overlayVisible = await page.evaluate((dialogSel) => {
          const d = [...document.querySelectorAll(dialogSel)].pop();
          const row = [...d.querySelectorAll("[data-setting-id]")].find((e) =>
            /overlay/i.test(e.getAttribute("data-setting-id")),
          );
          if (!row) return null;
          let box = row.parentElement;
          while (box && !/(auto|scroll)/.test(getComputedStyle(box).overflowY)) box = box.parentElement;
          const r = row.getBoundingClientRect();
          const b = box.getBoundingClientRect();
          return { id: row.getAttribute("data-setting-id"), rowTop: Math.round(r.top), boxTop: Math.round(b.top), boxBottom: Math.round(b.bottom), cls: row.className.slice(0, 200) };
        }, dialogSel);
        await page.waitForTimeout(1500);
        return {
          pass: states.every(([, v]) => v === "true") && overlayVisible && overlayVisible.rowTop >= overlayVisible.boxTop && overlayVisible.rowTop < overlayVisible.boxBottom,
          resultPicked: texts[idx].replace(/\n/g, " | "),
          collapsedBefore: collapsedBefore.map(([, v]) => v).join(","),
          states,
          overlayVisible,
          shot: flashShot,
          shotAfter: await shot("F-search-overlay-settled"),
        };
      });
      await step("G", async () => {
        const h = dialog.locator("[role=button][aria-expanded]").filter({ hasText: /^Identity$/ });
        await h.focus();
        const s0 = await h.getAttribute("aria-expanded");
        await page.keyboard.press("Enter");
        await page.waitForTimeout(200);
        const s1 = await h.getAttribute("aria-expanded");
        const focusShot = await shot("G-keyboard-after-enter");
        await page.keyboard.press(" ");
        await page.waitForTimeout(200);
        const s2 = await h.getAttribute("aria-expanded");
        const focused = await page.evaluate(() => document.activeElement?.textContent?.trim());
        return { pass: s0 === "true" && s1 === "false" && s2 === "true", s0, s1, s2, focused, shot: focusShot };
      });
    }

    // H: caller pages scrolled so a heading would be stuck (runs in both modes).
    await step("H", async () => {
      const out = {};
      await openNode("Claim");
      await scrollInto("Canvas", 150);
      await page.waitForTimeout(300);
      out.node = { m: await measure("Canvas"), shot: await shot("H-node-page") };

      await clickTab("Canvas");
      out.canvasTop = { m: await measure("Node on canvas"), shot: await shot("H-features-canvas-top") };
      await scrollInto("Node on canvas", 120);
      await page.waitForTimeout(300);
      out.canvas = { m: await measure("Node on canvas"), shot: await shot("H-features-canvas") };

      const lsVisible = await dialog
        .locator(".bp3-tab:not([aria-hidden='true'])")
        .filter({ hasText: /^Left sidebar$/ })
        .isVisible()
        .catch(() => false);
      if (lsVisible) {
        await clickTab("Left sidebar");
        out.leftSidebarTop = { m: await measure("Global"), shot: await shot("H-left-sidebar-top") };
        await scrollInto("Global", 120);
        await page.waitForTimeout(300);
        out.leftSidebar = { m: await measure("Global"), shot: await shot("H-left-sidebar") };
      } else out.leftSidebar = "skipped: tab hidden (left sidebar disabled)";

      await clickTab("General");
      out.generalTop = { m: await measure("Node trigger"), shot: await shot("H-general-top") };
      await scrollInto("Node trigger", 60);
      await page.waitForTimeout(300);
      out.general = { m: await measure("Node trigger"), shot: await shot("H-general") };
      return out;
    });

    if (MODE === "after") {
      await step("I", async () => {
        // Roam has no built-in dark theme; probe with Blueprint's bp3-dark on the dialog.
        const info = await page.evaluate(() => ({
          bodyClass: document.body.className,
          htmlClass: document.documentElement.className,
        }));
        await openNode("Claim");
        await scrollInto("Canvas", 150);
        await page.evaluate((dialogSel) => {
          document.querySelector(dialogSel)?.closest(".bp3-portal")?.classList.add("bp3-dark");
        }, dialogSel);
        await page.waitForTimeout(300);
        const m = await measure("Canvas");
        const p = await shot("I-bp3-dark-probe");
        await page.evaluate(() =>
          document.querySelectorAll(".bp3-portal.bp3-dark").forEach((e) => e.classList.remove("bp3-dark")),
        );
        return { info, m, shot: p };
      });
    }

    results.consoleErrors = consoleErrors;
    fs.writeFileSync(path.join(SHOT_DIR, `${MODE}-results.json`), JSON.stringify(results, null, 2));
    return { mode: MODE, summary: Object.fromEntries(Object.entries(results).map(([k, v]) => [k, v?.pass ?? (v?.error ? "ERROR" : "info")])) };
  },
};

