// ENG-2409 re-verify at b54dfd7f: inline dialog-matched heading bg, scoped realign scroll.
import fs from "node:fs";
import path from "node:path";

const SHOT_DIR =
  "/private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/23e2695a-e848-4726-8a24-c535b2593640/scratchpad/verify/shots";
const dialogSel = ".bp3-dialog:has(.dg-settings-tabs)";
const STYLE_ID = "dg-verify-custom-theme";

export default {
  async run({ page }) {
    const results = {};
    const consoleErrors = [];
    page.on("console", (m) => m.type() === "error" && consoleErrors.push(m.text().slice(0, 300)));
    page.on("pageerror", (e) => consoleErrors.push("pageerror: " + e.message));
    const dialog = page.locator(dialogSel).last();
    await dialog.waitFor({ timeout: 20000 });
    const shot = async (name) => {
      const p = path.join(SHOT_DIR, `after3-${name}.png`);
      await dialog.screenshot({ path: p });
      return p;
    };
    const clickTab = async (label) => {
      await dialog.locator(".bp3-tab").filter({ hasText: new RegExp(`^${label}$`) }).first().click();
      await page.waitForTimeout(600);
    };
    const openNode = async (name) => {
      await clickTab("Nodes");
      const back = dialog.locator("button[aria-label^='Back to']");
      for (let i = 0; i < 3 && (await back.count()); i++) {
        await back.first().click();
        await page.waitForTimeout(400);
      }
      await dialog.locator("td").filter({ hasText: new RegExp(`^${name}$`) }).first().click();
      await page.waitForTimeout(800);
    };
    const measure = (headingText) =>
      page.evaluate(
        ({ dialogSel, headingText }) => {
          const d = [...document.querySelectorAll(dialogSel)].pop();
          const all = [...d.querySelectorAll(".bp3-heading")];
          const h = all.find((e) => e.textContent.trim() === headingText);
          if (!h) return { found: false };
          let box = h.parentElement;
          while (box && !/(auto|scroll)/.test(getComputedStyle(box).overflowY)) box = box.parentElement;
          const cs = getComputedStyle(h);
          return {
            position: cs.position,
            inlineBg: h.style.backgroundColor,
            computedBg: cs.backgroundColor,
            dialogBg: getComputedStyle(d).backgroundColor,
            color: cs.color,
            headingTop: Math.round(h.getBoundingClientRect().top * 10) / 10,
            boxTop: Math.round(box.getBoundingClientRect().top * 10) / 10,
            scrollTop: box.scrollTop,
            ariaExpanded: h.getAttribute("aria-expanded"),
          };
        },
        { dialogSel, headingText },
      );
    const allHeadingBgs = () =>
      page.evaluate((dialogSel) => {
        const d = [...document.querySelectorAll(dialogSel)].pop();
        return [...d.querySelectorAll(".bp3-heading.sticky")].map((h) => [
          h.textContent.trim(),
          h.style.backgroundColor,
          getComputedStyle(h).color,
        ]);
      }, dialogSel);
    const scrollInto = (headingText, offset) =>
      page.evaluate(
        ({ dialogSel, headingText, offset }) => {
          const d = [...document.querySelectorAll(dialogSel)].pop();
          const h = [...d.querySelectorAll(".bp3-heading")].find((e) => e.textContent.trim() === headingText);
          let box = h.parentElement;
          while (box && !/(auto|scroll)/.test(getComputedStyle(box).overflowY)) box = box.parentElement;
          box.scrollTop += h.getBoundingClientRect().top - box.getBoundingClientRect().top + offset;
          return box.scrollTop;
        },
        { dialogSel, headingText, offset },
      );
    // scrollTop of every ancestor of the dialog plus the overlay scroll container.
    const outerScrolls = () =>
      page.evaluate((dialogSel) => {
        const d = [...document.querySelectorAll(dialogSel)].pop();
        const out = [];
        for (let n = d.parentElement; n; n = n.parentElement)
          out.push([(n.className && String(n.className).split(" ")[0]) || n.tagName, n.scrollTop]);
        const oc = d.closest(".bp3-overlay-scroll-container");
        return { overlayScrollContainer: oc ? oc.scrollTop : "none", ancestors: out, windowY: scrollY };
      }, dialogSel);
    const toggleAllBtn = () => dialog.locator("button").filter({ hasText: /^(Collapse all|Expand all)$/ });
    const expandAll = async () => {
      // Click until every section is open.
      for (let i = 0; i < 2; i++) {
        const anyClosed = await dialog.locator("[role=button][aria-expanded=false]").count();
        if (!anyClosed) return;
        await toggleAllBtn().click();
        await page.waitForTimeout(250);
      }
    };
    const step = async (key, fn) => {
      try {
        results[key] = await fn();
      } catch (e) {
        results[key] = { error: String(e?.message || e).slice(0, 400) };
        await shot(`${key}-error`).catch(() => {});
      }
    };
    const near = (a, b) => Math.abs(a - b) <= 2;
    const WHITE = "rgb(255, 255, 255)";

    // (1) Light mode.
    await step("C", async () => {
      await openNode("Claim");
      await expandAll();
      await scrollInto("Canvas", 150);
      await page.waitForTimeout(300);
      const m = await measure("Canvas");
      return { pass: m.position === "sticky" && m.inlineBg === WHITE && near(m.headingTop, m.boxTop), m, bgs: await allHeadingBgs(), shot: await shot("C-canvas-stuck") };
    });
    await step("D", async () => {
      const outerBefore = await outerScrolls();
      await dialog.locator("[role=button][aria-expanded]").filter({ hasText: /^Canvas$/ }).click();
      await page.waitForTimeout(400);
      const m = await measure("Canvas");
      const outerAfter = await outerScrolls();
      const outerMoved = JSON.stringify(outerBefore) !== JSON.stringify(outerAfter);
      return {
        pass: m.ariaExpanded === "false" && near(m.headingTop, m.boxTop) && !outerMoved && (outerAfter.overlayScrollContainer === 0 || outerAfter.overlayScrollContainer === "none"),
        m,
        outerMoved,
        outerBefore,
        outerAfter,
        shot: await shot("D-canvas-collapsed-from-stuck"),
      };
    });
    await step("H", async () => {
      const out = {};
      const vp = page.viewportSize() || (await page.evaluate(() => ({ width: innerWidth, height: innerHeight })));
      await page.setViewportSize({ width: vp.width, height: 640 });
      await page.waitForTimeout(500);
      await expandAll();
      await scrollInto("Canvas", 150);
      await page.waitForTimeout(300);
      out.node = { m: await measure("Canvas"), shot: await shot("H-node-page") };
      await clickTab("Canvas");
      await scrollInto("Node on canvas", 120);
      await page.waitForTimeout(300);
      out.canvas = { m: await measure("Node on canvas"), shot: await shot("H-features-canvas") };
      const ls = await dialog.locator(".bp3-tab").filter({ hasText: /^Left sidebar$/ }).isVisible().catch(() => false);
      if (ls) {
        await clickTab("Left sidebar");
        await scrollInto("Global", 40);
        await page.waitForTimeout(300);
        out.leftSidebar = { m: await measure("Global"), personal: await measure("Personal"), shot: await shot("H-left-sidebar") };
      } else out.leftSidebar = "skipped: tab hidden";
      await page.setViewportSize(vp);
      await page.waitForTimeout(500);
      const ms = [out.node.m, out.canvas.m, out.leftSidebar.m].filter(Boolean);
      out.pass = ms.every((m) => m.position === "sticky" && m.inlineBg === WHITE && near(m.headingTop, m.boxTop));
      return out;
    });

    // (2) Dark probe: bp3-dark on the portal, remount by switching tabs.
    await step("I_dark", async () => {
      await page.evaluate((dialogSel) => document.querySelector(dialogSel).closest(".bp3-portal").classList.add("bp3-dark"), dialogSel);
      await clickTab("General");
      await openNode("Claim");
      await expandAll();
      await scrollInto("Canvas", 150);
      await page.waitForTimeout(300);
      const m = await measure("Canvas");
      const bgs = await allHeadingBgs();
      const p1 = await shot("I-dark-node-page");
      await clickTab("Canvas");
      await scrollInto("Node on canvas", 120);
      await page.waitForTimeout(300);
      const mc = await measure("Node on canvas");
      const p2 = await shot("I-dark-features-canvas");
      await page.evaluate(() => document.querySelectorAll(".bp3-portal.bp3-dark").forEach((e) => e.classList.remove("bp3-dark")));
      await clickTab("General"); // remount back to light
      return {
        pass: m.inlineBg === m.dialogBg && mc.inlineBg === mc.dialogBg && bgs.every(([, bg]) => bg === m.dialogBg),
        m,
        mc,
        bgs,
        shots: [p1, p2],
      };
    });

    // (3) Custom theme: inject style, reopen dialog, headings must match.
    await step("I_custom", async () => {
      await page.keyboard.press("Escape");
      await page.waitForTimeout(600);
      const closed = (await page.locator(dialogSel).count()) === 0;
      if (!closed) {
        await page.mouse.click(5, 5);
        await page.waitForTimeout(600);
      }
      await page.evaluate((id) => {
        const s = document.createElement("style");
        s.id = id;
        s.textContent = ".bp3-dialog{background:#1e1e2e !important}";
        document.head.appendChild(s);
      }, STYLE_ID);
      await page.evaluate(() => window.__dgPlaywrightCommandCallbacks["DG: Open - Discourse settings"]());
      await dialog.waitFor({ timeout: 15000 });
      await page.waitForTimeout(800);
      await openNode("Claim");
      await scrollInto("Canvas", 150);
      await page.waitForTimeout(300);
      const m = await measure("Canvas");
      const bgs = await allHeadingBgs();
      const p1 = await shot("I-custom-theme-node-page");
      await clickTab("Canvas");
      await scrollInto("Node on canvas", 120);
      await page.waitForTimeout(300);
      const mc = await measure("Node on canvas");
      const p2 = await shot("I-custom-theme-features-canvas");
      const T = "rgb(30, 30, 46)";
      return { pass: m.inlineBg === T && mc.inlineBg === T && bgs.every(([, bg]) => bg === T), closedViaEscape: closed, m, mc, bgs, shots: [p1, p2] };
    });

    return results;
  },
  async cleanup({ page }) {
    const removed = await page.evaluate((id) => {
      const s = document.getElementById(id);
      s?.remove();
      document.querySelectorAll(".bp3-portal.bp3-dark").forEach((e) => e.classList.remove("bp3-dark"));
      return { styleRemoved: !!s, styleStillPresent: !!document.getElementById(id) };
    }, STYLE_ID);
    return removed;
  },
};

