        m,
        outerMoved,
        outerBefore,
        outerAfter,
        shot: await shot("D-canvas-collapsed-from-stuck"),
      };
    });
    await step("H", async () => {
      const out = {};
      const vp = page.viewportSize() || (await page.evaluate(() => ({ width: innerWidth, height: innerHeight })));
      await page.setViewportSize({ width: vp.width, height: 640 });
      await page.waitForTimeout(500);
      await expandAll();
      await scrollInto("Canvas", 150);
      await page.waitForTimeout(300);
      out.node = { m: await measure("Canvas"), shot: await shot("H-node-page") };
