    page.on("console", (m) => m.type() === "error" && consoleErrors.push(m.text().slice(0, 300)));
    page.on("pageerror", (e) => consoleErrors.push("pageerror: " + e.message));
    const dialog = page.locator(dialogSel).last();
    await dialog.waitFor({ timeout: 20000 });
    const shot = async (name) => {
      const p = path.join(SHOT_DIR, `after4-${name}.png`);
      await dialog.screenshot({ path: p });
      return p;
    };
    const wait = (ms) => page.waitForTimeout(ms);
    const clickTab = async (label) => {
      await dialog.locator(".bp3-tab").filter({ hasText: new RegExp(`^${label}$`) }).first().click();
      await wait(600);
    };
    const openNode = async (name) => {
      await clickTab("Nodes");
      const back = dialog.locator("button[aria-label^='Back to']");
      for (let i = 0; i < 3 && (await back.count()); i++) {
        await back.first().click();
        await wait(400);
      }
      await dialog.locator("td").filter({ hasText: new RegExp(`^${name}$`) }).first().click();
      await wait(800);
    };
    const measure = (headingText) =>
      page.evaluate(
        ({ dialogSel, headingText }) => {
          const d = [...document.querySelectorAll(dialogSel)].pop();
          const h = [...d.querySelectorAll(".bp3-heading")].find((e) => e.textContent.trim() === headingText);
          if (!h) return { found: false };
          let box = h.parentElement;
          while (box && !/(auto|scroll)/.test(getComputedStyle(box).overflowY)) box = box.parentElement;
          const cs = getComputedStyle(h);
          return {
            position: cs.position,
            inlineBg: h.style.backgroundColor,
            dialogBg: getComputedStyle(d).backgroundColor,
            color: cs.color,
            headingTop: Math.round(h.getBoundingClientRect().top * 10) / 10,
            boxTop: Math.round(box.getBoundingClientRect().top * 10) / 10,
            scrollTop: box.scrollTop,
            ariaExpanded: h.getAttribute("aria-expanded"),
          };
        },
        { dialogSel, headingText },
      );
    const collapses = () =>
      page.evaluate((dialogSel) => {
        const d = [...document.querySelectorAll(dialogSel)].pop();
        return [...d.querySelectorAll(".bp3-collapse")].map((c) => {
          const body = c.querySelector(":scope > .bp3-collapse-body");
          return {
            inlineHeight: c.style.height,
            rectHeight: Math.round(c.getBoundingClientRect().height),
            bodyAriaHidden: body?.getAttribute("aria-hidden") ?? null,
          };
        });
      }, dialogSel);
    const expandedStates = () =>
      page.evaluate((dialogSel) => {
        const d = [...document.querySelectorAll(dialogSel)].pop();
        return [...d.querySelectorAll("[role=button][aria-expanded]")].map((e) => [e.textContent.trim(), e.getAttribute("aria-expanded")]);
      }, dialogSel);
    const scrollInto = (headingText, offset) =>
      page.evaluate(
        ({ dialogSel, headingText, offset }) => {
          const d = [...document.querySelectorAll(dialogSel)].pop();
          const h = [...d.querySelectorAll(".bp3-heading")].find((e) => e.textContent.trim() === headingText);
          let box = h.parentElement;
          while (box && !/(auto|scroll)/.test(getComputedStyle(box).overflowY)) box = box.parentElement;
          box.scrollTop += h.getBoundingClientRect().top - box.getBoundingClientRect().top + offset;
          return box.scrollTop;
        },
        { dialogSel, headingText, offset },
      );
    const outerScrolls = () =>
      page.evaluate((dialogSel) => {
        const d = [...document.querySelectorAll(dialogSel)].pop();
        const out = [];
        for (let n = d.parentElement; n; n = n.parentElement) out.push(n.scrollTop);
        return out.join(",") + "|win" + scrollY;
      }, dialogSel);
    const toggleAllBtn = () => dialog.locator("button").filter({ hasText: /^(Collapse all|Expand all)$/ });
    const btnText = async () => (await toggleAllBtn().innerText()).trim();
    const setAll = async (open) => {
      for (let i = 0; i < 2; i++) {
        const states = await expandedStates();
        if (states.every(([, v]) => v === String(open))) return;
        await toggleAllBtn().click();
        await wait(350);
      }
    };
    // Samples the Canvas heading top and Collapse heights per frame while an action animates.
    const sampleDuring = (headingText, ms) =>
      page.evaluate(
        ({ dialogSel, headingText, ms }) =>
          new Promise((resolve) => {
            const d = [...document.querySelectorAll(dialogSel)].pop();
            const h = [...d.querySelectorAll(".bp3-heading")].find((e) => e.textContent.trim() === headingText);
            let box = h.parentElement;
            while (box && !/(auto|scroll)/.test(getComputedStyle(box).overflowY)) box = box.parentElement;
            const t0 = performance.now();
            const samples = [];
            const tick = () => {
              samples.push(Math.round(h.getBoundingClientRect().top - box.getBoundingClientRect().top));
              if (performance.now() - t0 < ms) requestAnimationFrame(tick);
              else resolve({ min: Math.min(...samples), max: Math.max(...samples), frames: samples.length, first: samples.slice(0, 8) });
